import itertools
import json
import numpy as np
import sympy as sp
from sympy.logic.boolalg import SOPform

# Decode each triple as a Boolean gate over abstract preceding signals.
# The gate tables are derived from its local weight coefficients, not by
# applying the network to input examples.
inputs = sp.symbols("x0:10")
signals = list(inputs)

def decode_gate(rows, biases, sources, is_first=False):
    coeffs = []
    for row in rows:
        c = [int(round(float(v))) for v in row[:10]]
        if not is_first:
            for j in range(10, 34, 3):
                a, b, d = (int(round(float(v))) for v in row[j:j+3])
                assert (a, b, d) == (a, a, -a)
                c.append(a)
        coeffs.append(c)

    used = [i for i in range(len(sources))
            if any(c[i] != 0 for c in coeffs)]
    formal = sp.symbols("z0:" + str(len(used)))
    minterms = []
    for bits in itertools.product((0, 1), repeat=len(used)):
        vals = [
            max(0, int(round(float(biases[r]))) +
                sum(coeffs[r][i] * bit for i, bit in zip(used, bits)))
            for r in range(3)
        ]
        value = vals[0] + vals[1] - vals[2]
        assert value in (0, 1), (value, used, bits)
        if value:
            minterms.append(bits)
    if not used:
        return sp.true if minterms else sp.false
    gate = SOPform(formal, minterms)
    return gate.xreplace({z: sources[i] for z, i in zip(formal, used)})

for layer in range(4):
    w = W[f"target.w{layer}"]
    b = W[f"target.b{layer}"]
    previous = list(inputs) if layer == 0 else signals
    signals = list(inputs) + [
        decode_gate(w[j:j+3], b[j:j+3], previous, layer == 0)
        for j in range(10, 34, 3)
    ]

# Decode the output classifier as a Boolean function of abstract signals.
out = W["target.out"]
bias = W["target.bias"]
head_coeffs = []
for row in out:
    c = [int(round(float(v))) for v in row[:10]]
    for j in range(10, 34, 3):
        a, b, d = (int(round(float(v))) for v in row[j:j+3])
        assert (a, b, d) == (a, a, -a)
        c.append(a)
    head_coeffs.append(c)

used = [i for i in range(len(signals))
        if any(c[i] != 0 for c in head_coeffs)]
formal = sp.symbols("q0:" + str(len(used)))
minterms = []
for bits in itertools.product((0, 1), repeat=len(used)):
    logits = [
        int(round(float(bias[r]))) +
        sum(head_coeffs[r][i] * bit for i, bit in zip(used, bits))
        for r in range(len(head_coeffs))
    ]
    winner = max(range(len(logits)), key=lambda r: logits[r])
    assert winner in (0, 1)
    if winner == 1:
        minterms.append(bits)

if used:
    expression = SOPform(formal, minterms).xreplace(
        {q: signals[i] for q, i in zip(formal, used)}
    )
else:
    expression = sp.true if minterms else sp.false

# Evaluate only the decoded Boolean expression.
def eval_expr(expr, x):
    if expr == sp.true:
        return True
    if expr == sp.false:
        return False
    if expr in inputs:
        return bool(x[inputs.index(expr)])
    if expr.func == sp.And:
        return all(eval_expr(a, x) for a in expr.args)
    if expr.func == sp.Or:
        return any(eval_expr(a, x) for a in expr.args)
    if expr.func == sp.Not:
        return not eval_expr(expr.args[0], x)
    if expr.func == sp.Xor:
        return sum(eval_expr(a, x) for a in expr.args) % 2 == 1
    raise ValueError(expr)

sub = {
    "outputs": [
        int(eval_expr(expression, bits))
        for bits in itertools.product((0, 1), repeat=10)
    ]
}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
